398	  /**
399	   * The recorded frame summaries strictly after `afterTick`, up to `limit`, in
400	   * tick order. The log must be contiguous from the requested point; the window
401	   * is re-derived in memory from the snapshot before it and must reproduce every
402	   * recorded hash - a divergence is an integrity failure rather than a silently
403	   * different catch-up. Nothing here mutates the frame log.
404	   */
405	  sessionFrames(matchId, afterTick, limit, frontier) {
406	    const end = Math.min(afterTick + limit, frontier);
407	    const byTick = new Map();
408	    for (const frame of this.store.readFramesFrom(matchId, afterTick + 1)) {
409	      byTick.set(frame.tick, frame);
410	    }
411	    const frames = [];
412	    for (let tick = afterTick + 1; tick <= end; tick += 1) {
413	      const frame = byTick.get(tick);
414	      if (!frame) {
415	        // Every tick up to the frontier must have a frame; a gap means the log
416	        // was corrupted and catch-up cannot be served continuously.
417	        throw new IntegrityError(`match ${matchId} is missing recorded frame ${tick}`);
418	      }
419	      frames.push({
420	        casualties: frame.delta.casualties, settled: frame.settled,
421	        state_hash: frame.state_hash, tick: frame.tick,
422	      });
423	    }
424	    if (frames.length > 0) {
425	      this.verifyWindow(matchId, afterTick, frames);
426	    }
427	    return frames;
428	  }
