430	  /**
431	   * Recompute the frames of a catch-up window in memory from the snapshot before
432	   * it and the stored input log, comparing each hash with the recorded one. This
433	   * is the read-only counterpart of the rollback rebuild: session catch-up never
434	   * trims or rewrites the frame log.
435	   */
436	  verifyWindow(matchId, afterTick, frames) {
437	    const state = this.snapshotAt(matchId, afterTick);
438	    const buckets = new Map();
439	    for (const input of this.store.readInputs(matchId)) {
440	      const bucket = buckets.get(input.tick);
441	      if (bucket) {
442	        bucket.push(input.body);
443	      } else {
444	        buckets.set(input.tick, [input.body]);
445	      }
446	    }
447	    for (const bucket of buckets.values()) {
448	      bucket.sort(sim.compareInputs);
449	    }
450	    for (const frame of frames) {
451	      const settled = buckets.get(state.tick) || [];
452	      sim.applyTick(state, settled);
453	      state.hash = sim.stateHash(state);
454	      if (state.tick !== frame.tick || state.hash !== frame.state_hash) {
455	        throw new IntegrityError(`frame ${frame.tick} of match ${matchId} does not recompute to its recorded hash`);
456	      }
457	    }
458	  }
