460	  /** Hash of the state *after* frame `tick`; 0 is the initial (frontier) hash. */
461	  frameHashAt(matchId, tick) {
462	    if (tick <= 0) {
463	      return sim.stateHash(sim.initialState(this.config(matchId)));
464	    }
465	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
466	    if (!frame) {
467	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
468	    }
469	    return frame.state_hash;
470	  }
471	
472	  /** Team damage at frame `tick`, taken from the frame snapshot when mid-window. */
473	  teamDamageAt(matchId, tick, current) {
474	    if (tick >= current.tick) {
475	      return { blue: current.teamDamage.blue, red: current.teamDamage.red };
476	    }
477	    if (tick <= 0) {
478	      return { blue: 0, red: 0 };
479	    }
480	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
481	    if (!frame) {
482	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
483	    }
484	    return { blue: frame.state.teams.blue, red: frame.state.teams.red };
485	  }
