487	  /** Snapshots of the session-owned units as they are at frame `tick`. */
488	  unitsAt(matchId, unitIds, tick, current) {
489	    let source;
490	    if (tick >= current.tick) {
491	      source = current.units;
492	    } else if (tick <= 0) {
493	      source = sim.initialState(this.config(matchId)).units;
494	    } else {
495	      const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
496	      if (!frame) {
497	        throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
498	      }
499	      source = {};
500	      for (const unit of frame.state.units) {
501	        source[unit.id] = unit;
502	      }
503	    }
504	    return unitIds.map((id) => {
505	      const unit = source[id];
506	      if (!unit) {
507	        throw new IntegrityError(`frame ${tick} of match ${matchId} is missing unit ${id}`);
508	      }
509	      return {
510	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
511	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
512	      };
