526	  /**
527	   * The frame a spectator may currently see: the frontier delayed by
528	   * `delay_ticks` while a match runs, or the final tick once it has ended. A
529	   * finished match is frozen, so its spectators catch up to the very end instead
530	   * of trailing forever.
531	   */
532	  visibleTick(spectator, state) {
533	    if (state.status !== 'running') {
534	      return state.tick;
535	    }
