539	  /**
540	   * Register a spectator: a passive reader that trails the live frontier by
541	   * `delay_ticks`. Spectators are bookkeeping only: creating one never advances
542	   * the match and never enters a `state_hash` or `replay_hash`.
543	   */
544	  createSpectator(matchId, raw, key) {
545	    const record = this.match(matchId);
546	    sim.exactKeys(raw, ['id', 'delay_ticks'], 'body');
547	    if (raw.id === undefined || raw.delay_ticks === undefined) {
548	      throw new ValidationError('body must contain id and delay_ticks');
549	    }
550	    const spectatorId = sim.identifier(raw.id, 'spectator id');
551	    const delayTicks = sim.integer(raw.delay_ticks, 'delay_ticks', 0, MAX_SPECTATOR_DELAY);
552	    return this.idempotent(key, `create-spectator:${matchId}`, raw, () => {
553	      if (this.store.readSpectator(matchId, spectatorId)) {
554	        throw new ConflictError(`spectator ${spectatorId} already exists for match ${matchId}`);
555	      }
556	      const spectator = { delayTicks, highWater: 0, id: spectatorId, maxDelivered: 0, reset: false };
557	      this.store.insertSpectator(matchId, spectator);
558	      const state = this.store.readState(matchId);
559	      return {
560	        delay_ticks: delayTicks,
561	        match_id: matchId,
562	        spectator_id: spectatorId,
563	        visible_tick: this.visibleTick(spectator, state),
