568	  /**
569	   * Poll a spectator's delayed stream.
570	   *
571	   * In normal `stream` mode the response carries the contiguous recorded frames
572	   * strictly after `after_tick` up to the spectator's `visible_tick`, at most
573	   * `limit` frames, followed by the state at the end of the returned window.
574	   * `complete` is true only when the window reached `visible_tick`.
575	   *
576	   * When a rollback (a late input or the explicit endpoint) rewrites a frame the
577	   * spectator had already received, the spectator is marked for reset: the next
578	   * poll ignores `after_tick`, replays from tick 0 in pages of `limit`, and
579	   * reports `mode: "reset"` until the reset stream catches back up.
580	   */
581	  pollSpectator(matchId, spectatorId, raw, key) {
582	    const spectator = this.requireSpectator(matchId, spectatorId);
583	    sim.exactKeys(raw, ['after_tick', 'limit'], 'body');
584	    const afterTick = raw.after_tick === undefined ? 0 : raw.after_tick;
585	    if (!Number.isInteger(afterTick) || afterTick < 0) {
586	      throw new ValidationError('after_tick must be a non-negative integer');
587	    }
588	    const limit = raw.limit === undefined ? sim.MAX_STEP : raw.limit;
589	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
590	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
591	    }
592	    return this.idempotent(key, `poll-spectator:${matchId}:${spectatorId}`, raw, () => {
593	      const state = this.store.readState(matchId);
594	      const visible = this.visibleTick(spectator, state);
595	      if (!spectator.reset && afterTick > visible) {
596	        throw new ConflictError(`after_tick ${afterTick} is past the visible tick ${visible}`);
597	      }
598	
599	      let mode = 'stream';
600	      let startTick = afterTick;
601	      if (spectator.reset) {
602	        // A reset replays the whole history from tick 0 in limit-sized pages;
603	        // after_tick from the client is discarded. The spectator's high-water
604	        // mark, rewound to 0 when the reset was flagged, is the paging cursor.
605	        mode = 'reset';
606	        startTick = spectator.highWater;
607	      }
608	
609	      const end = Math.min(startTick + limit, visible);
610	      const frames = this.spectatorFrames(matchId, startTick, end);
611	      const reached = startTick + frames.length;
612	
613	      let complete;
614	      let nextReset = spectator.reset;
615	      if (spectator.reset) {
616	        complete = reached >= visible;
617	        nextReset = !complete;
618	      } else {
619	        complete = reached >= visible;
620	      }
621	
622	      const updated = {
623	        ...spectator,
624	        highWater: reached,
625	        maxDelivered: Math.max(spectator.maxDelivered, reached),
626	        reset: nextReset,
627	      };
