630	      return {
631	        complete,
632	        frames,
633	        match_id: matchId,
634	        mode,
635	        next_tick: reached,
636	        spectator_id: spectatorId,
637	        state_hash: this.frameHashAt(matchId, reached),
638	        team_damage: this.teamDamageAt(matchId, reached, state),
639	        units: this.allUnitsAt(matchId, reached, state),
640	      };
641	    });
642	  }
