773	        inputs: frame.inputs.map((canonical) => ({
774	          participant: JSON.parse(canonical).unit,
775	          payload: canonical,
776	        })),
777	        stateHash: frame.state_hash,
778	        tick: frame.tick,
779	      });
780	    }
781	    return writer.finalize();
782	  }
