852	    }
853	    const expected = new Map();
854	    for (const frame of this.store.readFramesFrom(matchId, resumeTick + 1)) {
855	      expected.set(frame.tick, frame.state_hash);
856	    }
857	    // `resumeTick` is a *frame* number: resuming continues from the state that
858	    // frame recorded, and must read it before the log is trimmed.
859	    const state = this.snapshotAt(matchId, resumeTick);
860	    const resumeStatus = state.status;
