863	    // discards must restart from tick 0. A plain forward advance never reaches
864	    // this branch with such a spectator: its visible window lags the frontier,
865	    // so its high-water mark cannot pass the old frontier.
866	    for (const spectator of this.store.readSpectatorsPast(matchId, resumeTick)) {
867	      // Rewind the reset paging cursor to 0 so the replay restarts at tick 0.
868	      // The monotonic max-delivered mark is kept: it is what triggered this and
869	      // continues to describe how far this spectator has ever seen.
870	      spectator.highWater = 0;
871	      spectator.reset = true;
872	      this.store.writeSpectator(matchId, spectator);
873	    }
874	    const buckets = new Map();
875	    for (const input of this.store.readInputs(matchId)) {
876	      const bucket = buckets.get(input.tick);
877	      if (bucket) {
878	        bucket.push(input.body);
879	      } else {
880	        buckets.set(input.tick, [input.body]);
881	      }
882	    }
883	    for (const bucket of buckets.values()) {
884	      bucket.sort(sim.compareInputs);
885	    }
886	
887	    state.status = 'running';
888	    const boundary = extend ? config.maxTicks : targetTick;
889	    const rebuilt = [];
890	    let endedNaturally = false;
891	    // Iteration `produced` applies the inputs of tick `produced - 1` and records
892	    // frame `produced`.
