3	const { createServer: buildServer } = require('node:http');
4	const { LockstepError, NotFoundError, ValidationError } = require('./errors');
5	const { Lockstep } = require('./service');
6	
7	/**
8	 * Minimal HTTP layer over the Lockstep service.
9	 *
10	 * Routing, request decoding, error mapping and the standard error envelope live
11	 * here; every product rule lives in `service.js`, `replay.js` and `sim.js`.
12	 */
13	const MAX_BODY_BYTES = 1_000_000;
14	
15	function readBody(request) {
16	  return new Promise((resolve, reject) => {
17	    const contentType = request.headers['content-type'];
18	    if (contentType === undefined || String(contentType).split(';')[0].trim().toLowerCase() !== 'application/json') {
19	      reject(new ValidationError('Content-Type must be application/json'));
20	      return;
21	    }
22	    const chunks = [];
23	    let size = 0;
24	    request.on('data', (chunk) => {
25	      size += chunk.length;
26	      if (size > MAX_BODY_BYTES) {
27	        reject(new ValidationError('request body must be at most 1000000 bytes'));
28	        request.destroy();
29	        return;
30	      }
31	      chunks.push(chunk);
32	    });
33	    request.on('end', () => {
34	      if (chunks.length === 0) {
35	        resolve(null);
36	        return;
37	      }
38	      try {
39	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
40	      } catch {
41	        reject(new ValidationError('request body must be valid JSON'));
42	      }
43	    });
44	    request.on('error', reject);
45	  });
46	}
47	
48	function send(response, status, payload) {
49	  const body = Buffer.from(JSON.stringify(payload), 'utf8');
50	  response.writeHead(status, {
51	    'Content-Length': body.length,
52	    'Content-Type': 'application/json; charset=utf-8',
53	  });
54	  response.end(body);
55	}
56	
57	function sendBytes(response, status, body, contentType) {
58	  response.writeHead(status, {
59	    'Content-Length': body.length,
60	    'Content-Type': contentType,
61	  });
62	  response.end(body);
63	}
64	
65	/** Read an optional JSON body: a request with no Content-Type carries no body. */
66	function readOptionalBody(request) {
67	  if (request.headers['content-type'] === undefined) {
68	    return Promise.resolve(null);
69	  }
70	  return readBody(request);
71	}
72	
73	function createHandler(service) {
74	  return async function handle(request, response) {
75	    try {
76	      const parts = new URL(request.url, 'http://localhost').pathname.split('/').filter((part) => part.length > 0);
77	      const { method } = request;
78	      const key = request.headers['idempotency-key'];
79	
80	      if (method === 'GET' && parts.length === 1 && parts[0] === 'health') {
81	        send(response, 200, { service: 'lockstepnet', status: 'ok' });
82	        return;
83	      }
84	      if (method === 'POST' && parts.length === 1 && parts[0] === 'matches') {
85	        send(response, 201, service.createMatch(await readBody(request), key));
86	        return;
87	      }
88	      if (parts.length >= 2 && parts[0] === 'matches') {
89	        const id = decodeURIComponent(parts[1]);
90	        if (method === 'GET' && parts.length === 2) {
91	          send(response, 200, service.getState(id));
92	          return;
93	        }
94	        if (method === 'GET' && parts.length === 3 && parts[2] === 'replay') {
95	          send(response, 200, service.replayFile(id));
96	          return;
97	        }
98	        if (method === 'GET' && parts.length === 3 && parts[2] === 'replay.stream') {
99	          sendBytes(response, 200, service.replayStream(id), 'application/octet-stream');
100	          return;
101	        }
102	        if (method === 'POST' && parts.length === 3 && parts[2] === 'inputs') {
103	          send(response, 201, service.submitInputs(id, await readBody(request), key));
104	          return;
105	        }
106	        if (method === 'POST' && parts.length === 3 && parts[2] === 'tick') {
107	          send(response, 200, service.advance(id, await readBody(request), key));
108	          return;
109	        }
110	        if (method === 'POST' && parts.length === 3 && parts[2] === 'rollback') {
111	          const body = await readBody(request);
112	          if (!body || typeof body !== 'object' || Array.isArray(body) || !Number.isInteger(body.tick)) {
113	            throw new ValidationError('body must contain an integer tick');
114	          }
115	          for (const field of Object.keys(body)) {
116	            if (field !== 'tick') {
117	              throw new ValidationError(`body has unknown field ${field}`);
118	            }
119	          }
120	          send(response, 200, service.rollback(id, body.tick));
121	          return;
