const {spawn} = require('node:child_process');
const child = spawn(process.execPath, ['src/server.js','--host','127.0.0.1','--port','18096','--database','/tmp/timing.db'], {stdio:['ignore','pipe','pipe']});
child.stdout.on('data', (c) => { if (c.toString().includes('listening on')) { console.log('started'); child.kill(); process.exit(0);} });
setTimeout(()=>{console.log('TIMEOUT'); child.kill(); process.exit(1);}, 30000);
